with input as (select data_text_trim_v1(?1) as name), rejected as (select name,case when name='' or data_text_char_count_v1(name)>500 then 'invalidNameLength' when exists(select 1 from json_each('['||replace(data_json_quote_v1(name),'`','","')||']') where data_text_trim_v1(value)='') then 'emptyNameContext' when data_text_char_count_v1(?1)>500 then 'conceptFieldsTooLong' end as reason from input) select reason,case reason when 'invalidNameLength' then '概念名称须为 1–500 个字符' when 'emptyNameContext' then '分隔符前的名称和分隔符后的语境均不能为空' when 'conceptFieldsTooLong' then '概念字段超过允许长度' end,name,data_text_trim_v1(?2),'从旧文献归类迁移，保持原身份区分','','','' from rejected